import { GoogleGenAI } from "@google/genai";
import { ChatMessage } from "../types";

const SYSTEM_INSTRUCTION = `
You are "Fit For Cancer", an AI assistant specifically designed for people undergoing cancer treatment in Australia.
Your goal is to provide evidence-based exercise and nutrition advice based on guidelines from the Clinical Oncology Society of Australia (COSA) and the Cancer Council.

Key Rules:
1. Always encourage users to consult their oncology team before starting a new routine.
2. Focus on "Movement as Medicine" - helping reduce cancer-related fatigue.
3. Provide simple, easy-to-digest meal suggestions for side effects like nausea, metallic taste, or low appetite.
4. Keep the tone empathetic, professional, and supportive.
5. Use Australian spelling and measurements (e.g., Celsius, grams, kilometers).
6. If asked about medications, clarify you are an exercise/nutrition AI and they must speak to their oncologist.
`;

export const getGeminiResponse = async (history: ChatMessage[]) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Convert our chat history to Gemini's format
  const contents = history.map(msg => ({
    role: msg.role,
    parts: [{ text: msg.content }]
  }));

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: contents,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.7,
      },
    });

    return response.text || "I'm sorry, I couldn't generate a response. Please try again.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "There was an error connecting to the health assistant. Please check your connection.";
  }
};

